<style>
.ec13-page .tc-contact-page{--tc-accent:var(--ec13-green-dark,#357525);background:#f6f7f6;color:#202b26;padding-bottom:56px}
.ec13-page .tc-contact-container{width:min(1240px,calc(100% - 48px))}.ec13-page .tc-contact-breadcrumb{padding:18px 0;color:#68716b;font-size:12px}.ec13-page .tc-contact-heading{max-width:840px;padding:6px 0 14px}.ec13-page .tc-contact-heading>span{color:var(--ec13-green-dark,#357525);font-size:12px;font-weight:700}.ec13-page .tc-contact-heading h1{font-size:clamp(27px,3vw,36px);line-height:1.25;letter-spacing:-.4px;margin:8px 0 12px;color:#202b26}.ec13-page .tc-contact-heading p{font-size:14px;line-height:1.7;color:#626d65;margin:0}.ec13-page .tc-contact-copy{font-size:14px;line-height:1.7;color:#626d65;margin:0 0 22px;max-width:840px}.ec13-page .tc-contact-copy p{margin:0}
.ec13-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.4fr);gap:24px;align-items:start}.ec13-page .tc-contact-info{background:#fff;border:1px solid #e0e5df;border-top:3px solid var(--ec13-green-dark,#357525);border-radius:8px;padding:26px}.ec13-page .tc-contact-info h2,.ec13-page .tc-contact-form-card h2{font-size:23px;color:#202b26;margin:0 0 10px}.ec13-page .tc-contact-info>p,.ec13-page .tc-contact-form-card>p{font-size:13px;line-height:1.7;color:#69736c;margin:0 0 20px}.ec13-page .tc-contact-item{padding:18px 0;border-color:#e8ece7;gap:14px}.ec13-page .tc-contact-item>.tc-contact-icon{background:#eef5eb;color:var(--ec13-green-dark,#357525);border-radius:6px;flex-basis:40px;height:40px}.ec13-page .tc-contact-item h3{font-size:12px;color:#69736c;margin:0 0 6px}.ec13-page .tc-contact-item a,.ec13-page .tc-contact-item p{font-size:14px;color:#26342b;line-height:1.7;overflow-wrap:anywhere}.ec13-page .tc-contact-item .tc-contact-directions{display:inline-block;color:var(--ec13-green-dark,#357525);font-size:12px;margin-top:10px;font-weight:600}.ec13-page .tc-contact-item a:hover{text-decoration:underline}
.ec13-page .tc-contact-form-card{background:#fff;border:1px solid #e0e5df;border-radius:8px;padding:26px;box-shadow:none}.ec13-page .tc-contact-fields{gap:16px}.ec13-page .tc-contact-fields label{font-size:13px;color:#26342b;font-weight:600}.ec13-page .tc-contact-fields input,.ec13-page .tc-contact-fields textarea{background:#fff;border:1px solid #cfd7cf;border-radius:5px;font:inherit;font-size:14px;color:#202b26;padding:11px 12px;box-shadow:none}.ec13-page .tc-contact-fields input{height:44px}.ec13-page .tc-contact-fields textarea{min-height:120px;resize:vertical}.ec13-page .tc-contact-fields input:focus,.ec13-page .tc-contact-fields textarea:focus{outline:2px solid #a9ce97;outline-offset:2px;border-color:var(--ec13-green-dark,#357525)}.ec13-page .tc-contact-fields small{font-size:12px;color:#69736c}.ec13-page .tc-contact-form-card button[type=submit]{background:var(--ec13-green-dark,#357525);color:#fff;border:0;border-radius:5px;min-height:46px;margin-top:20px;padding:12px 24px;font:inherit;font-size:14px;font-weight:700;box-shadow:none;cursor:pointer}.ec13-page .tc-contact-form-card button[type=submit]:hover{background:#285c1c}.ec13-page .tc-contact-form-card button:focus-visible{outline:3px solid #a9ce97;outline-offset:3px}.ec13-page .tc-contact-fields [aria-invalid=true]{border-color:#b42318;background:#fff8f7}
@media(max-width:800px){.ec13-page .tc-contact-layout{grid-template-columns:1fr}}@media(max-width:480px){.ec13-page .tc-contact-container{width:calc(100% - 32px)}.ec13-page .tc-contact-info,.ec13-page .tc-contact-form-card{padding:22px 18px}.ec13-page .tc-contact-fields{grid-template-columns:1fr}.ec13-page .tc-contact-form-card button[type=submit]{width:100%}}
</style>
